from agents.sql_agent import run_sql_agent
from agents.retrieval_agent import run_retrieval_agent

EXPECTED_KEYS = {"success", "answer", "sources", "metadata"}


def check_agent(name, agent, question):
    result = agent(question)

    if not isinstance(result, dict):
        raise AssertionError(f"{name} must return a dict; got {type(result).__name__}")

    keys = set(result.keys())
    print(f"{name} keys: {sorted(keys)}")

    if keys != EXPECTED_KEYS:
        raise AssertionError(
            f"{name} returned keys {sorted(keys)}; expected {sorted(EXPECTED_KEYS)}"
        )

    expected_types = {
        "success": bool,
        "answer": str,
        "sources": list,
        "metadata": dict,
    }
    for key, expected_type in expected_types.items():
        if not isinstance(result[key], expected_type):
            raise AssertionError(
                f"{name}.{key} must be {expected_type.__name__}; "
                f"got {type(result[key]).__name__}"
            )

    print(f"{name}: PASS")


check_agent(
    "run_sql_agent",
    run_sql_agent,
    "How many clients are in the database?",
)
check_agent(
    "run_retrieval_agent",
    run_retrieval_agent,
    "What information is available in the documents?",
)
